const KEYS = new Set(exports.SITE_COPY_ENTRIES.map((e) => e[0]));

/** Whether a dotted key is one this catalogue covers. The write path
 *  refuses anything else, so a typo is a 422 at save time rather than an
 *  override that silently never renders. */
exports.isSiteCopyKey = (key) => KEYS.has(key);

/** Every key, for a caller that needs the list rather than the test. */
exports.siteCopyKeys = () => [...KEYS];
